```js
const express = require('express');
const session = require('express-session');
const argon2 = require('argon2');
const { RateLimiterMemory } = require('rate-limiter-flexible');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET not set');
const prod = process.env.NODE_ENV === 'production';

const app = express();
if (prod) app.set('trust proxy', 1); // one reverse proxy in front; needed for req.ip and secure cookies
app.use(express.json());
app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', secure: prod, maxAge: 8 * 60 * 60 * 1000 },
}));

// Demo store. Replace with a DB.
const users = new Map(); // username -> { id, username, hash }
let nextId = 1;

// Failed attempts only. Window starts at the first failure.
const WINDOW_S = 15 * 60;
const failsByUserIp = new RateLimiterMemory({ points: 5, duration: WINDOW_S });
const failsByIp = new RateLimiterMemory({ points: 50, duration: WINDOW_S });

// Verified when the user does not exist, so response time does not reveal valid usernames.
const dummyHash = argon2.hash('dummy-password');

async function msBlocked(limiter, key) {
  const r = await limiter.get(key);
  return r && r.consumedPoints >= limiter.points ? r.msBeforeNext : 0;
}

function credentials(req) {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  return { username: username.trim().toLowerCase(), password };
}

app.post('/register', async (req, res) => {
  const c = credentials(req);
  if (!c || !c.username || c.password.length < 8) {
    return res.status(400).json({ error: 'username and password (min 8 chars) required' });
  }
  if (users.has(c.username)) return res.status(409).json({ error: 'username taken' });
  const hash = await argon2.hash(c.password); // argon2id, salt embedded
  users.set(c.username, { id: nextId++, username: c.username, hash });
  res.status(201).json({ ok: true });
});

app.post('/login', async (req, res, next) => {
  const c = credentials(req);
  if (!c) return res.status(400).json({ error: 'username and password required' });

  const ipKey = req.ip;
  const userIpKey = `${c.username}|${req.ip}`;

  const wait = Math.max(
    await msBlocked(failsByIp, ipKey),
    await msBlocked(failsByUserIp, userIpKey),
  );
  if (wait > 0) {
    res.set('Retry-After', String(Math.ceil(wait / 1000)));
    return res.status(429).json({ error: 'too many failed attempts' });
  }

  const user = users.get(c.username);
  const ok = await argon2.verify(user ? user.hash : await dummyHash, c.password);

  if (!user || !ok) {
    // consume() rejects once over the limit; the check above handles blocking.
    await Promise.allSettled([failsByIp.consume(ipKey), failsByUserIp.consume(userIpKey)]);
    return res.status(401).json({ error: 'invalid username or password' });
  }

  await failsByUserIp.delete(userIpKey);

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    req.session.username = user.username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'not logged in' });
  next();
}

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.listen(process.env.PORT || 3000);
```

Run: `SESSION_SECRET=$(openssl rand -hex 32) node app.js`

Behavior:
- **Hashing:** argon2id through `argon2.hash` / `argon2.verify`.
- **Sessions:** cookie `sid`, `httpOnly`, `sameSite=lax`, `secure` in production, 8-hour lifetime.
- **Rate limit:** 5 failures per username+IP or 50 failures per IP in 15 minutes gives `429` with `Retry-After`. Successful login clears the username+IP counter only.

Before production:
- **Stores:** sessions (default `MemoryStore`) and limiters live in process memory. Restart wipes them and multiple instances do not share them. Use Redis: `connect-redis` and `RateLimiterRedis`.
- **Proxy:** `trust proxy` is set to 1 in production. Wrong hop count makes `req.ip` wrong or spoofable, which breaks the limiter.
- **CSRF:** `sameSite=lax` is the only CSRF defense here. Add tokens if you serve cross-site forms.
